// Some portions generated by Codex
import assert from "node:assert/strict";
import test from "node:test";
import { languageLiteralPresentation } from "../../../main/frontend/graph-explorer/literal-language-presentation.ts";

test("language literal presentation preserves the language tag and base direction", () => {
  assert.deepEqual(languageLiteralPresentation({ language: "ar", direction: "rtl" }), {
    dir: "rtl",
    languageLabel: "ar--rtl",
  });
});

test("language literal presentation keeps nondirectional labels compatible", () => {
  assert.deepEqual(languageLiteralPresentation({ language: "en" }), {
    dir: undefined,
    languageLabel: "en",
  });
});

test("language literal presentation omits metadata when there is no language tag", () => {
  assert.deepEqual(languageLiteralPresentation({}), {
    dir: undefined,
    languageLabel: undefined,
  });
});
